// Code generated by fin-protoc. DO NOT EDIT.
//
// Decoded strings borrow from the input buffer and stay valid only while the
// input bytes do; deinit frees only the outer repeat slices allocated by
// decode. Requires the `binary_codec` module (fin-proto-runtime-bin-zig).

const std = @import("std");
const codec = @import("binary_codec");

pub const ExecRptInfo = struct {
    platform_id: u16,
    pbu: []const []const u8,
    set_id: []const u32,

    pub fn encode(self: *const ExecRptInfo, buf: *codec.Buffer) !void {
        try buf.put(u16, self.platform_id);
        try codec.putFixedStringList(u16, buf, self.pbu, 8);
        try codec.putList(u32, u16, buf, self.set_id);
    }

    pub fn decode(allocator: std.mem.Allocator, r: *codec.Reader) codec.DecodeError!ExecRptInfo {
        const platform_id = try r.get(u16);
        const pbu = try codec.getFixedStringList(u16, allocator, r, 8);
        const set_id = try codec.getList(u32, u16, allocator, r);
        return .{
            .platform_id = platform_id,
            .pbu = pbu,
            .set_id = set_id,
        };
    }

    pub fn deinit(self: ExecRptInfo, allocator: std.mem.Allocator) void {
        allocator.free(self.pbu);
        allocator.free(self.set_id);
    }

    pub fn eql(self: ExecRptInfo, other: ExecRptInfo) bool {
        if (self.platform_id != other.platform_id) return false;
        if (self.pbu.len != other.pbu.len) return false;
        for (self.pbu, other.pbu) |a, b| {
            if (!std.mem.eql(u8, a, b)) return false;
        }
        if (self.set_id.len != other.set_id.len) return false;
        for (self.set_id, other.set_id) |a, b| {
            if (a != b) return false;
        }
        return true;
    }
};

test "test_exec_rpt_info_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = ExecRptInfo{
        .platform_id = 1234,
        .pbu = &[_][]const u8{ "a", "a", "a", "a", "a", "a", "a", "a" },
        .set_id = &[_]u32{ 123456, 654321 },
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try ExecRptInfo.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    try std.testing.expect(msg.eql(decoded));
}
